inline double muffin_weight(float tau1decayMode, float ptratio, float tau1Pt, float nsmalljets, float nbtags, float tau1Eta, float tau1Phi) {
    const float x[7] = {tau1decayMode, ptratio, tau1Pt, nsmalljets, nbtags, tau1Eta, tau1Phi};
  return MUFFIN_1TAU1L::eval(x, MUFFIN_1TAU1L::FEAT_nominal, MUFFIN_1TAU1L::THR_nominal, MUFFIN_1TAU1L::LEFT_nominal,
                  MUFFIN_1TAU1L::RIGHT_nominal, MUFFIN_1TAU1L::MISS_nominal, MUFFIN_1TAU1L::OFF_nominal,
                  MUFFIN_1TAU1L::NTREE_nominal, MUFFIN_1TAU1L::B0_nominal, MUFFIN_1TAU1L::NORM_nominal);
}

